`timescale 1ns / 1ps
//
// Font ROM - 8x16, generated by gen_font_rom.py - do not edit
// 53 glyphs, 848 bytes
//
// One BSRAM read port. Registered output: assert char_code/row on
// cycle N, pixel row data is valid on cycle N+1.
//
module font_rom (
    input  wire       clk,
    input  wire [7:0] char_code,   // ASCII
    input  wire [3:0] row,         // 0..15 within the 16-row cell
    output reg  [7:0] bits         // MSB = leftmost pixel
);

    // ---- ASCII -> compact glyph index (constant, folds into LUTs) ----
    reg [5:0] gidx;
    always @(*) begin
        case (char_code)
            8'd33 : gidx = 6'd1;   // '!'
            8'd35 : gidx = 6'd2;   // '#'
            8'd37 : gidx = 6'd3;   // '%'
            8'd40 : gidx = 6'd4;   // '('
            8'd41 : gidx = 6'd5;   // ')'
            8'd42 : gidx = 6'd6;   // '*'
            8'd43 : gidx = 6'd7;   // '+'
            8'd44 : gidx = 6'd8;   // ','
            8'd45 : gidx = 6'd9;   // '-'
            8'd46 : gidx = 6'd10;   // '.'
            8'd47 : gidx = 6'd11;   // '/'
            8'd48 : gidx = 6'd12;   // '0'
            8'd49 : gidx = 6'd13;   // '1'
            8'd50 : gidx = 6'd14;   // '2'
            8'd51 : gidx = 6'd15;   // '3'
            8'd52 : gidx = 6'd16;   // '4'
            8'd53 : gidx = 6'd17;   // '5'
            8'd54 : gidx = 6'd18;   // '6'
            8'd55 : gidx = 6'd19;   // '7'
            8'd56 : gidx = 6'd20;   // '8'
            8'd57 : gidx = 6'd21;   // '9'
            8'd58 : gidx = 6'd22;   // ':'
            8'd60 : gidx = 6'd23;   // '<'
            8'd61 : gidx = 6'd24;   // '='
            8'd62 : gidx = 6'd25;   // '>'
            8'd63 : gidx = 6'd26;   // '?'
            8'd65 : gidx = 6'd27;   // 'A'
            8'd66 : gidx = 6'd28;   // 'B'
            8'd67 : gidx = 6'd29;   // 'C'
            8'd68 : gidx = 6'd30;   // 'D'
            8'd69 : gidx = 6'd31;   // 'E'
            8'd70 : gidx = 6'd32;   // 'F'
            8'd71 : gidx = 6'd33;   // 'G'
            8'd72 : gidx = 6'd34;   // 'H'
            8'd73 : gidx = 6'd35;   // 'I'
            8'd74 : gidx = 6'd36;   // 'J'
            8'd75 : gidx = 6'd37;   // 'K'
            8'd76 : gidx = 6'd38;   // 'L'
            8'd77 : gidx = 6'd39;   // 'M'
            8'd78 : gidx = 6'd40;   // 'N'
            8'd79 : gidx = 6'd41;   // 'O'
            8'd80 : gidx = 6'd42;   // 'P'
            8'd81 : gidx = 6'd43;   // 'Q'
            8'd82 : gidx = 6'd44;   // 'R'
            8'd83 : gidx = 6'd45;   // 'S'
            8'd84 : gidx = 6'd46;   // 'T'
            8'd85 : gidx = 6'd47;   // 'U'
            8'd86 : gidx = 6'd48;   // 'V'
            8'd87 : gidx = 6'd49;   // 'W'
            8'd88 : gidx = 6'd50;   // 'X'
            8'd89 : gidx = 6'd51;   // 'Y'
            8'd90 : gidx = 6'd52;   // 'Z'
            default: gidx = 6'd0;      // blank
        endcase
    end

    // ---- bitmap table ----
    (* ram_style = "block" *) reg [7:0] rom [0:847];

    // Path is overridable so the same source works when run from the
    // project root (simulation) and from the Gowin project dir (synth).
`ifndef FONT_ROM_HEX
  `define FONT_ROM_HEX "rtl/font_rom.hex"
`endif

    initial $readmemh(`FONT_ROM_HEX, rom);

    wire [10:0] addr = {gidx, row};   // gidx*16 + row

    always @(posedge clk)
        bits <= rom[addr];

endmodule
